<?php
require_once __DIR__.'/integration/TestBootstrap.php';$db=DagrilIntegrationTest::boot();
require_once __DIR__.'/../app/models/User.php';require_once __DIR__.'/../app/models/AccessControl.php';
$actor=DagrilIntegrationTest::loginRole('administrateur');$model=new User();
$site=(int)DagrilIntegrationTest::scalar("SELECT id FROM sites WHERE code='BOUCH'");
$db->exec(file_get_contents(__DIR__.'/../database/038_add_butchery_manager_role.sql'));
$role=(int)DagrilIntegrationTest::scalar("SELECT id FROM roles WHERE slug='responsable-boucherie'");
$base=['name'=>'Test parcours utilisateur','email'=>'user-access-'.bin2hex(random_bytes(5)).'@example.test','phone'=>'','password'=>'Test-password-123','status'=>'active','site_ids'=>[$site],'account_role_id'=>$role,'account_role_site_id'=>$site,'access_mode'=>'now'];
$id=$model->createAccount($base,$actor);
DagrilIntegrationTest::check((int)DagrilIntegrationTest::scalar("SELECT COUNT(*) FROM user_role_assignments WHERE user_id=? AND approval_status='approved'",[$id])===1,'Création du compte et du rôle en une opération');
$model->updateAccount($id,array_replace($base,['password'=>'']),$actor);
DagrilIntegrationTest::check((int)DagrilIntegrationTest::scalar('SELECT COUNT(*) FROM user_role_assignments WHERE user_id=?',[$id])===1,'Modification sans doublon de rôle');
$bad=array_replace($base,['email'=>'bad-'.$base['email'],'account_role_site_id'=>999999]);
DagrilIntegrationTest::expectException(fn()=>$model->createAccount($bad,$actor),'Site hors périmètre refusé');
DagrilIntegrationTest::check(!(bool)DagrilIntegrationTest::scalar('SELECT id FROM users WHERE email=?',[$bad['email']]),'Échec du rôle annule aussi le compte');
$sensitive=(int)DagrilIntegrationTest::scalar("SELECT id FROM roles WHERE slug='administrateur'");
$id2=$model->createAccount(array_replace($base,['email'=>'sensitive-'.$base['email'],'account_role_id'=>$sensitive]),$actor);
DagrilIntegrationTest::check(DagrilIntegrationTest::scalar('SELECT approval_status FROM user_role_assignments WHERE user_id=?',[$id2])==='pending','Un rôle sensible reste soumis à une seconde approbation');
$pendingId=(int)DagrilIntegrationTest::scalar('SELECT id FROM user_role_assignments WHERE user_id=?',[$id2]);
$changes=array_replace($base,['email'=>'sensitive-'.$base['email'],'password'=>'','account_role_id'=>0,'access_mode'=>'later','access_decisions'=>[$pendingId=>'approve']]);
DagrilIntegrationTest::expectException(fn()=>$model->updateAccount($id2,$changes,$actor),'Auto-approbation sensible refusée depuis la fiche');
DagrilIntegrationTest::check(DagrilIntegrationTest::scalar('SELECT approval_status FROM user_role_assignments WHERE id=?',[$pendingId])==='pending','Refus conserve le rôle en attente');
$wrong=array_replace($base,['password'=>'','account_role_id'=>0,'access_mode'=>'later','access_decisions'=>[$pendingId=>'revoke']]);
DagrilIntegrationTest::expectException(fn()=>$model->updateAccount($id,$wrong,$actor),'Accès d’un autre utilisateur refusé');
$delegation=array_replace($base,['email'=>'delegation-'.$base['email'],'account_assignment_type'=>'delegation','account_expires_at'=>'']);
DagrilIntegrationTest::expectException(fn()=>$model->createAccount($delegation,$actor),'Délégation sans expiration refusée');
$u=DagrilIntegrationTest::row('SELECT * FROM users WHERE id=?',[$id]);Auth::login($u);Auth::selectSite((string)$site);
DagrilIntegrationTest::check(Auth::can('butchery','create',$site)&&Auth::can('butchery','validate',$site)&&!Auth::can('butchery','delete',$site)&&!Auth::can('users','administer'),'Permissions boucherie limitées au métier demandé');
DagrilIntegrationTest::check(!Auth::can('butchery','read',1),'Autre site exclu');
DagrilIntegrationTest::loginRole('administrateur');
$assignmentId=(int)DagrilIntegrationTest::scalar('SELECT id FROM user_role_assignments WHERE user_id=?',[$id]);
$model->updateAccount($id,array_replace($base,['password'=>'','account_role_id'=>0,'access_mode'=>'later','access_decisions'=>[$assignmentId=>'revoke']]),$actor);
DagrilIntegrationTest::check(DagrilIntegrationTest::scalar('SELECT approval_status FROM user_role_assignments WHERE id=?',[$assignmentId])==='revoked','Révocation depuis la fiche enregistrée et journalisée');
DagrilIntegrationTest::finish();
